/**
 * The 11-chapter spine + seed questions.
 *
 * Seed questions are hardcoded opening questions for each chapter — the
 * first question is NEVER generated by the LLM, eliminating any risk of
 * reasoning/leakage on Q1. The LLM only generates Q2+ (follow-up questions),
 * which is much easier because it has conversation history to work with.
 *
 * Inspired by the working app's ChapterConstants.seedQuestions.
 */

export interface ChapterDef {
  order: number
  title: string
  prompt: string
  seedQuestion: string // hardcoded opening question — no LLM call needed
}

export const CHAPTERS: ChapterDef[] = [
  {
    order: 1,
    title: 'Origins',
    prompt: 'Where the subject comes from — birth, awakening, manifestation, or first appearance.',
    seedQuestion: "What's your first memory? Not something you were told, something you actually remember.",
  },
  {
    order: 2,
    title: 'Childhood',
    prompt: 'The earliest remembered experiences. The first world the subject knew.',
    seedQuestion: "What did your world look like when you were small? Who was in it?",
  },
  {
    order: 3,
    title: 'Adolescence',
    prompt: 'The period when the subject began to separate from their first world.',
    seedQuestion: "When did you first realize you were different from the world around you?",
  },
  {
    order: 4,
    title: 'Family & Kin',
    prompt: 'Who the subject considers kin — blood, choice, species, mentor, pack.',
    seedQuestion: "Who did you consider your people? Who mattered most to you?",
  },
  {
    order: 5,
    title: 'Education / What Was Learned',
    prompt: 'How the subject learned what they know.',
    seedQuestion: "How did you learn what you know? Who taught you, or did you teach yourself?",
  },
  {
    order: 6,
    title: 'Love & Relationships',
    prompt: 'The people who mattered. Attachment, devotion, desire, rejection, separation.',
    seedQuestion: "Who was the first person who mattered to you in a way you couldn't explain?",
  },
  {
    order: 7,
    title: 'Parenthood / Creation',
    prompt: 'What the subject made, raised, begot, built, or unleashed.',
    seedQuestion: "What did you bring into being? What did you make, or raise, or unleash?",
  },
  {
    order: 8,
    title: 'Loss',
    prompt: 'What was lost. The absences that shape the subject.',
    seedQuestion: "What's the first absence that shaped you? What did you lose that you can't get back?",
  },
  {
    order: 9,
    title: 'Turning Points',
    prompt: 'The moments after which nothing was the same.',
    seedQuestion: "When did everything change? What was the moment after which nothing was the same?",
  },
  {
    order: 10,
    title: 'Lessons Learned',
    prompt: 'What the subject now understands that they did not understand before.',
    seedQuestion: "What do you understand now that you didn't understand before? What took you longest to learn?",
  },
  {
    order: 11,
    title: 'Legacy',
    prompt: 'What the subject leaves behind, intends to leave, or refuses to leave.',
    seedQuestion: "What do you leave behind? Or what do you refuse to leave?",
  },
]

export function chapterByOrder(order: number): ChapterDef | undefined {
  return CHAPTERS.find((c) => c.order === order)
}

export function getSeedQuestion(order: number): string {
  return chapterByOrder(order)?.seedQuestion ?? 'Tell me about yourself.'
}
